        { type: 'case', story: 'В классном чате кто-то выложил обидный мем про тебя. Многие ставят смайлики.', q: 'Что ты сделаешь?', a: [
          { t: 'Напишу в ответ что-нибудь ещё обиднее', ok: false, why: 'Ответ разжигает ссору ещё сильнее. Обидчикам как раз этого и надо.' },
          { t: 'Сделаю скрин, выйду из чата и расскажу взрослому', ok: true, why: 'Верно! Скрин — доказательство, а взрослый поможет разобраться.' },
          { t: 'Удалю приложение и никому не скажу', ok: 'mid', why: 'Отдохнуть от чата можно, но без взрослых травля может продолжиться.' }
        ], why: 'Кибербуллинг: не отвечай, скрин, блок, расскажи взрослому.' },
        { type: 'case', story: 'Одноклассники снимают на телефон, как Лену толкают в раздевалке, и зовут тебя посмотреть.', q: 'Что ты сделаешь?', a: [
          { t: 'Тоже сниму — потом всем покажу', ok: false, why: 'Видео сделает Лене ещё больнее и разнесёт травлю дальше.' },
          { t: 'Скажу «Хватит!» и позову учителя', ok: true, why: 'Отлично! Ты заступился и позвал того, кто может остановить обидчиков.' },
          { t: 'Отвернусь и уйду', ok: 'mid', why: 'Ты не участвуешь — уже хорошо. Но позвать взрослого было бы гораздо полезнее.' }
        ], why: 'Не снимаем, не смеёмся. Поддерживаем и зовём взрослого.' },
        { type: 'case', story: 'Подруга рассказала, что её травят, и просит: «Только никому не говори».', q: 'Что ты сделаешь?', a: [
          { t: 'Буду молчать — я же обещала', ok: 'mid', why: 'Хорошо, что подруга доверилась тебе, но это плохой секрет: одной ей не справиться.' },
          { t: 'Поддержу её и предложу вместе пойти к взрослому', ok: true, why: 'Супер! Так ты и поддерживаешь, и помогаешь по-настоящему.' },
          { t: 'Расскажу всему классу', ok: false, why: 'Так можно сделать подруге ещё хуже. Рассказывать нужно взрослому, которому доверяешь.' }
        ], why: 'О травле рассказываем взрослому — это помощь, а не предательство.' },
        { type: 'one', q: 'Что из этого буллинг?', a: ['Один раз поспорили из-за мяча', 'Каждый день обзывают одного и того же', 'Друг не дал списать', 'Проиграл в игре'], c: 1, why: 'Буллинг — когда одного человека обижают снова и снова.' },
        { type: 'one', q: 'Детский телефон доверия:', a: ['8-800-2000-122', '01', '8-800-555-35-35', '911'], c: 0, why: '8-800-2000-122 — бесплатно и анонимно, там выслушают и помогут.' },
        { type: 'tf', q: 'Если тебя травят, значит, с тобой что-то не так.', c: false, why: 'Ты не виноват. Неправильно ведут себя обидчики.' },
        { type: 'tf', q: 'Сообщить взрослому о травле — это не ябедничество.', c: true, why: 'Это защита человека, которому плохо.' },
        { type: 'sort', q: 'Как вести себя, если видишь травлю?', groups: ['🟢 Помогает', '🔴 Вредит'], items: [['Позвать в свою компанию', 0], ['Сказать учителю', 0], ['Сказать «Хватит!»', 0], ['Смеяться вместе со всеми', 1], ['Снимать на видео', 1], ['Пересылать обидный мем', 1]], why: 'Поддержка и взрослые помогают. Смех, видео и пересылка делают травлю сильнее.' },
        { type: 'order', q: 'Расставь шаги по порядку: тебе пишут обидное в интернете.', items: ['Не отвечать обидчику', 'Сделать скриншот', 'Заблокировать', 'Рассказать взрослому'], why: 'Без ответа обидчик не получит реакции, а скрин поможет взрослым.' }
